FIXTURE = {
    k: base64.b64decode(v) for k, v in json.loads(zlib.decompress(base64.b85decode(PACKED))).items()
}


def encode(value):
    return (json.dumps(value, sort_keys=True, indent=2) + "\n").encode()


class PublicationDependencyTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name).resolve()
        self.input = self.root / "selected"
        self.input.mkdir()
        self.paths = {}
        rows = []
        for index, role in enumerate(receiver.ROLES):
            p = self.input / f"{index:03d}-{role}.body"
            p.write_bytes(FIXTURE[role])
            self.paths[role] = p
            rows.append(
                dict(
                    role=role,
                    path=str(p),
                    size_bytes=p.stat().st_size,
                    sha256=receiver.sha(p.read_bytes()),
                )
            )
        self.manifest = dict(
            schema=receiver.INPUT_SCHEMA,
            fixture_origin="retained_signed_successor_publication",
            selected_files=rows,
        )
        self.path = self.input / "manifest.json"
        self.path.write_bytes(encode(self.manifest))
        self.output = self.root / "output"

    def raw_metadata(self):
        return dict(FIXTURE)

    def change(self, role, value):
        raw = value if type(value) is bytes else encode(value)
        p = self.paths[role]
        p.write_bytes(raw)
        row = self.manifest["selected_files"][receiver.ROLES.index(role)]
        row.update(size_bytes=len(raw), sha256=receiver.sha(raw))
        self.path.write_bytes(encode(self.manifest))

    def run_audit(self):
        return receiver.audit(self.path, self.output)

    def capture(self, mutate):
        value = receiver.document(FIXTURE["generation3_manifest"])
        h = receiver.document(FIXTURE["owners_after"])["source"]["current_head"]
        mutate(value)
        h["manifest_cid"] = receiver.object_cid(value)
        return receiver.capture(value, h)

    def test_retained_generation_and_three_distinct_change_denominators(self):
        r = self.run_audit()
        self.assertEqual(r["generation_delta"]["unchanged_entry_count"], 299)
        self.assertEqual(r["generation_delta"]["unchanged_unit_count"], 3)
        self.assertEqual(r["generation_delta"]["changed_unit_count"], 297)
        self.assertEqual(r["generation_delta"]["unchanged_entry_changed_ast_count"], 296)
        self.assertEqual(r["changed_symbols"][0]["signature_unchanged"], True)
        self.assertEqual(
            (
                r["unchanged_symbol_count"],
                r["changed_symbol_count"],
                r["changed_function_version_count"],
            ),
            (588, 2, 1),
        )
        self.assertEqual(
            r["declared_dependency_frontier"]["affected_paths"],
            ["check_offset.py", "check_type.py"],
        )
        self.assertEqual(
            (
                r["declared_dependency_frontier"]["incoming_edge_count"],
                r["declared_dependency_frontier"]["unresolved_frontier_count"],
            ),
            (4, 3),
        )
        self.assertEqual(
            [s["return_operand_order"] for s in r["archived_source_syntax"]],
            ["name_then_constant", "constant_then_name"],
        )
        self.assertTrue(all(r[k] is True for k in receiver.TRUE))
        self.assertTrue(all(r[k] is False for k in receiver.FALSE))
        self.assertTrue(all(type(r[k]) is int and r[k] == 0 for k in receiver.ZERO))
        self.assertEqual(
            set(p.name for p in self.output.iterdir()),
            {"inputs", "input.json", receiver.REPORT_NAME},
        )
        self.assertEqual(len(list((self.output / "inputs").iterdir())), 13)

    def test_exact_origins_and_retained_copies_are_identical(self):
        r = self.run_audit()
        for row in r["selected_files"]:
            self.assertEqual(
                Path(row["path"]).read_bytes(), Path(row["retained_path"]).read_bytes()
            )
        self.assertEqual(self.path.read_bytes(), (self.output / "input.json").read_bytes())

    def test_semantic_stable_id_sets_survive_but_function_version_changes(self):
        r = receiver.derive(self.raw_metadata())
        changed = {x["kind"]: x for x in r["changed_symbols"]}
        self.assertFalse(changed["module"]["version_changed"])
        self.assertTrue(changed["function"]["version_changed"])
        self.assertNotEqual(
            changed["module"]["previous_source_cid"], changed["module"]["published_source_cid"]
        )
        self.assertFalse(r["inherited_scan_staleness"]["refusal_reperformed"])

    def test_raw_byte_alias_and_physical_alias_are_separate(self):
        self.paths["generation3_calc_source"].unlink()
        os.link(self.paths["generation2_calc_source"], self.paths["generation3_calc_source"])
        row = self.manifest["selected_files"][9]
        row.update(size_bytes=47, sha256=receiver.sha(FIXTURE["generation2_calc_source"]))
        self.path.write_bytes(encode(self.manifest))
        with self.assertRaises(receiver.Refused):
            self.run_audit()

    def test_source_is_parsed_without_executing_an_arbitrary_call(self):
        raw = b"def increment(n: int) -> int:\n    return __import__('os').system('false')\n"
        self.change("generation3_calc_source", raw)
        with self.assertRaises(receiver.Refused):
            self.run_audit()

    def test_input_directory_symlink_refused(self):
        link = self.root / "alias"
        link.symlink_to(self.input, target_is_directory=True)
        with self.assertRaises(receiver.Refused):
            receiver.audit(link / "manifest.json", self.output)

    def test_selected_file_symlink_refused(self):
        p = self.paths["generation3_calc_source"]
        original = self.root / "real"
        p.rename(original)
        p.symlink_to(original)
        with self.assertRaises(receiver.Refused):
            self.run_audit()

    def test_no_original_output_nesting(self):
        with self.assertRaises(receiver.Refused):
            receiver.audit(self.path, self.input / "nested")

    def test_output_reuse_refused(self):
        self.output.mkdir()
        with self.assertRaises(receiver.Refused):
            self.run_audit()

    def test_reservation_file_count_bound(self):
        reads = receiver.Reads()
        with mock.patch.object(receiver, "MAX_FILES", 1):
            reads.reserve(self.path, self.path.stat().st_size)
            with self.assertRaises(receiver.Refused):
                reads.reserve(self.paths["native_result"], len(FIXTURE["native_result"]))

    def test_reservation_total_body_bound(self):
        with mock.patch.object(receiver, "MAX_TOTAL", 20):
            with self.assertRaises(receiver.Refused):
                self.run_audit()

    def test_report_allocation_bound(self):
        with mock.patch.object(receiver, "MAX_REPORT", 100):
            with self.assertRaises(receiver.Refused):
                self.run_audit()

    def test_returned_report_is_detached_from_raw_body_late_reread(self):
        r = self.run_audit()
        r["native_execution_performed"] = True
        stored = receiver.document((self.output / receiver.REPORT_NAME).read_bytes())
        self.assertIs(stored["native_execution_performed"], False)


def manifest_control(name, mutate):
    def test(self):
        mutate(self.manifest)
        self.path.write_bytes(encode(self.manifest))
        with self.assertRaises((receiver.Refused, KeyError, TypeError, ValueError)):
            self.run_audit()

    setattr(PublicationDependencyTests, "test_manifest_" + name, test)


for name, mutate in (
    ("unknown_field", lambda d: d.update(extra=True)),
    ("wrong_schema", lambda d: d.update(schema="future@2")),
    ("wrong_origin", lambda d: d.update(fixture_origin="authored")),
    ("reversed_roles", lambda d: d["selected_files"].reverse()),
    ("missing_role", lambda d: d["selected_files"].pop()),
    ("duplicate_role", lambda d: d["selected_files"][1].update(role="native_result")),
    ("descriptor_unknown", lambda d: d["selected_files"][0].update(extra=True)),
    ("boolean_size", lambda d: d["selected_files"][0].update(size_bytes=True)),
    ("oversized_body", lambda d: d["selected_files"][0].update(size_bytes=receiver.MAX_BODY + 1)),
    (
        "uppercase_digest",
        lambda d: d["selected_files"][0].update(sha256=d["selected_files"][0]["sha256"].upper()),
    ),
    ("stale_digest", lambda d: d["selected_files"][0].update(sha256="0" * 64)),
    ("relative_path", lambda d: d["selected_files"][0].update(path="local.json")),
):
    manifest_control(name, mutate)


def metadata_control(name, role, mutate):
    def test(self):
        d = receiver.document(FIXTURE[role])
        mutate(d)
        self.change(role, d)
        with self.assertRaises((receiver.Refused, KeyError, TypeError, ValueError)):
            self.run_audit()

    setattr(PublicationDependencyTests, "test_repaired_metadata_" + name, test)


